mapper.select:
SELECT product_id, status, created_at, updated_at
FROM app_iot_product_profile
WHERE product_id = #{productId}

SELECT product_id, status, created_at, updated_at FROM app_iot_product_profile WHERE product_id IN
#{productId}
ORDER BY product_id

mapper.update:
UPDATE app_iot_product_profile
SET status = #{status}
WHERE product_id = #{productId}

