mapper.delete:
WITH expired AS (
    SELECT idempotency_key
    FROM app_iot_device_creation_request
    WHERE expires_at <= #{now}
    ORDER BY expires_at, idempotency_key
    LIMIT #{batchSize}
)
DELETE FROM app_iot_device_creation_request AS request
USING expired
WHERE request.idempotency_key = expired.idempotency_key

mapper.update:
UPDATE app_iot_device_creation_request
SET status = 'COMPLETE', response_key_id = #{responseKeyId},
    response_ciphertext = #{responseCiphertext}
WHERE idempotency_key = #{idempotencyKey}
  AND request_hash = #{requestHash}
  AND status = 'PENDING'

mapper.select:
SELECT idempotency_key, request_hash, response_key_id, response_ciphertext, expires_at
FROM app_iot_device_creation_request
WHERE idempotency_key = #{idempotencyKey}
  AND status = 'COMPLETE'
  AND expires_at > #{now}
